import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {buildTimeline,cueAt} from './timeline.mjs';
const m=JSON.parse(fs.readFileSync(new URL('../story/story_manifest.json',import.meta.url))),v=JSON.parse(fs.readFileSync(new URL('../../engine2/voices/manifest.json',import.meta.url)));
test('all 399 recordings bind to exact speaker and text in isolated beats',()=>{const used=new Set();for(const r of m.text_records){const t=buildTimeline(r.text_verbatim,v.lines);assert.ok(t.duration>0);let end=0;for(const c of t.turns){assert.equal(c.start,end);assert.ok(c.end>c.start);end=c.end;if(c.audio){const l=v.lines.find(l=>l.audio===c.audio);assert.equal(l.speaker,c.speaker);assert.equal(l.text,c.body.trim());assert.equal(c.duration,l.duration_seconds);used.add(c.audio);assert.ok(fs.existsSync(new URL('../../engine2/voices/'+c.audio,import.meta.url)));}}assert.equal(t.duration,end);}assert.equal(used.size,399);});
test('turn boundaries switch at the exact next recorded cue',()=>{const t=buildTimeline('SABLE: First.\nIONA: Second.',[{speaker:'Sable',text:'First.',audio:'a.mp3',duration_seconds:2},{speaker:'Iona',text:'Second.',audio:'b.mp3',duration_seconds:3}]);assert.equal(cueAt(t,1.999).speaker,'Sable');assert.equal(cueAt(t,2).speaker,'Iona');assert.equal(t.duration,5);});
test('missing voices and receipts stay silent and visible',()=>{const t=buildTimeline('SABLE: Missing.\nReceived: 5 credits',[]);assert.ok(t.turns.every(c=>!c.audio));assert.ok(t.turns.some(c=>c.status.includes('Received: 5 credits')));});
